//go:build ignore

// Copy into upstream converter/xlsx and run TestCodexXLSXStyles.
package xlsx
import("archive/zip";"bytes";"encoding/json";"fmt";"math/rand";"os";"path/filepath";"sort";"testing")
func TestCodexXLSXStyles(t *testing.T){root:=os.Getenv("BDF_FIXTURE_ROOT");if root==""{t.Fatal("BDF_FIXTURE_ROOT required")};samples:=[][]byte{};for _,name:=range []string{"basic.xlsx","features.xlsx","form-fixed.xlsx","form-pages.xlsx","form-rows.xlsx","math.xlsx","print.xlsx"}{b,e:=os.ReadFile(filepath.Join("testdata",name));if e!=nil{t.Fatal(e)};samples=append(samples,b)};r:=rand.New(rand.NewSource(511389));fonts:=[]string{`<font><name val="Arial"/><sz val="10"/><b/><color rgb="FF112233"/></font>`,`<font><name val="ＭＳ 明朝"/><sz val="13.5"/><i val="1"/><u val="double"/><family val="2"/><scheme val="major"/></font>`,`<font><strike val="0"/><u val="none"/><color theme="4" tint="0.5"/><vertAlign val="superscript"/></font>`,`<font><color indexed="9"/><b val="false"/><sz val="-1"/></font>`,`<font><color auto="1"/><name val=""/></font>`,`<font/>`};align:=[]string{``,`<alignment horizontal="center" vertical="top" wrapText="1"/>`,`<alignment horizontal="right" shrinkToFit="1" indent="2" textRotation="45"/>`,`<alignment textRotation="255" justifyLastLine="true"/>`,`<alignment textRotation="200"/>`};for i:=0;i<1000;i++{var b bytes.Buffer;z:=zip.NewWriter(&b);add:=func(name,content string){f,e:=z.Create(name);if e!=nil{t.Fatal(e)};f.Write([]byte(content))};add("xl/workbook.xml",`<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"/>`);if i%13!=0 {add("xl/_rels/workbook.xml.rels",`<Relationships><Relationship Id="rId1" Type="x/styles" Target="styles.xml"/></Relationships>`);s:=`<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts>`;for j:=0;j<r.Intn(4);j++{s+=fmt.Sprintf(`<numFmt numFmtId="%d" formatCode="%s"/>`,164+j,[]string{"0.00","yyyy-mm-dd","0%","General"}[r.Intn(4)])};s+="</numFmts><fonts>";for j:=0;j<r.Intn(5);j++{s+=fonts[r.Intn(len(fonts))]};s+="</fonts><cellStyleXfs>";for j:=0;j<r.Intn(3);j++{s+=fmt.Sprintf(`<xf numFmtId="%d" fontId="%d">%s</xf>`,r.Intn(20),r.Intn(5),align[r.Intn(len(align))])};s+="</cellStyleXfs><cellXfs>";for j:=0;j<r.Intn(6);j++{s+=fmt.Sprintf(`<xf numFmtId="%d" fontId="%d" fillId="%d" borderId="%d" xfId="%d" applyAlignment="%d">%s</xf>`,r.Intn(170),r.Intn(5),r.Intn(4),r.Intn(4),r.Intn(3),r.Intn(2),align[r.Intn(len(align))])};s+="</cellXfs></styleSheet>";add("xl/styles.xml",s)};if e:=z.Close();e!=nil{t.Fatal(e)};samples=append(samples,append([]byte{},b.Bytes()...))};out:=[]any{};for _,data:=range samples{c,_,e:=openWorkbook(bytes.NewReader(data),int64(len(data)),&Options{NoSystemFonts:true,SystemFonts:true});if e!=nil{t.Fatal(e)};st:=c.st;fs:=[]any{};for _,f:=range st.fonts{co:=f.color;fs=append(fs,[]any{f.name,f.size,f.bold,f.italic,f.underline,f.strike,int(co.kind),co.rgb.R,co.rgb.G,co.rgb.B,co.idx,co.tint,f.vert,f.scheme,f.family})};ids:=[]int{};for id:=range st.numFmts{ids=append(ids,id)};sort.Ints(ids);formats:=[]any{};for _,id:=range ids{formats=append(formats,[]any{id,st.numFmts[id]})};xfs:=[]any{};for _,x:=range st.cellXfs{a:=x.align;xfs=append(xfs,[]any{x.numFmt,x.font,x.fill,x.border,a.h,a.v,a.wrap,a.shrink,a.indent,a.rotation,a.justifyLast})};out=append(out,map[string]any{"input":data,"want":[]any{fs,formats,xfs}})};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/xlsx/styles.json"),b,0644);e!=nil{t.Fatal(e)}}
